// Rectangular pool area estimate — no invented price or material quantity.
const estimateForm=document.getElementById('estimate-form'),numberFormat=new Intl.NumberFormat('fa-IR',{maximumFractionDigits:2});
function dimensions(){const f=new FormData(estimateForm);return ['length','width','depth'].map(key=>Number(f.get(key)));}
function calculateArea(focusResult=false){const [l,w,d]=dimensions();const error=document.getElementById('estimate-error');if(!estimateForm.checkValidity()||![l,w,d].every(n=>Number.isFinite(n)&&n>0)){error.textContent='ابعاد را به‌صورت عدد مثبت و در محدوده مشخص‌شده وارد کنید.';return false;}error.textContent='';const floor=l*w,walls=2*(l+w)*d;document.getElementById('estimate-total').textContent=numberFormat.format(floor+walls);document.getElementById('estimate-floor').value=numberFormat.format(floor);document.getElementById('estimate-walls').value=numberFormat.format(walls);if(focusResult)document.getElementById('estimate-result').focus({preventScroll:true});return true;}
estimateForm.addEventListener('submit',e=>{e.preventDefault();calculateArea(true);});
estimateForm.querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>{document.getElementById('estimate-total').textContent='—';document.getElementById('estimate-floor').value='—';document.getElementById('estimate-walls').value='—';document.getElementById('estimate-error').textContent='برای به‌روزرسانی نتیجه، محاسبه متراژ را بزنید.';}));
document.getElementById('reset-estimate').addEventListener('click',()=>{estimateForm.reset();calculateArea();});
let messageTimer;function toast(message){const el=document.getElementById('interaction-toast');el.textContent=message;clearTimeout(messageTimer);messageTimer=setTimeout(()=>el.textContent='',4000);}
async function copySummary(text){try{if(navigator.clipboard&&isSecureContext)await navigator.clipboard.writeText(text);else{const field=document.createElement('textarea');field.value=text;field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();const copied=document.execCommand('copy');field.remove();if(!copied)throw Error('copy');}toast('خلاصه ابعاد و متراژ کپی شد.');}catch{toast('کپی خودکار ممکن نشد. خلاصه ابعاد را از نتیجه محاسبه بردارید.');}}
document.getElementById('copy-estimate').addEventListener('click',()=>{if(!calculateArea()){estimateForm.reportValidity();return;}const [l,w,d]=dimensions();copySummary('استخر مستطیلی با عمق ثابت\nطول: '+l+' متر\nعرض: '+w+' متر\nعمق: '+d+' متر\nمساحت کف و دیواره‌ها: '+numberFormat.format(l*w+2*(l+w)*d)+' مترمربع\nبرآورد اولیه، بدون پله، شیب، بازشو و پرت مصالح.');});
// Search visible FAQ text, preserving the original content in the document.
function normalizeFa(text){return text.replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\u200c\u200f\u200e]/g,' ').replace(/\s+/g,' ').trim().toLowerCase();}
const faqQuery=document.getElementById('faq-query');function filterFaq(){const q=normalizeFa(faqQuery.value),terms=q.split(' ').filter(Boolean);let matches=0;questions.forEach(item=>{const text=normalizeFa(item.textContent);const match=terms.every(term=>text.includes(term));item.hidden=!match;if(match)matches++;});document.getElementById('faq-empty').hidden=matches>0;document.getElementById('faq-result-count').textContent=q?numberFormat.format(matches)+' پاسخ مرتبط':'';updateScroll();}
faqQuery.addEventListener('input',filterFaq);document.getElementById('reset-faq').addEventListener('click',()=>{faqQuery.value='';filterFaq();faqQuery.focus();});
// Native dialog handles focus trapping and Escape; arrow keys follow RTL gallery order.
const gallery=document.getElementById('gallery-dialog'),projectButtons=[...document.querySelectorAll('.project-trigger')];let galleryIndex=0,galleryOpener=null;
function renderGallery(index){galleryIndex=(index+projectButtons.length)%projectButtons.length;const button=projectButtons[galleryIndex],img=button.querySelector('img');const target=document.getElementById('gallery-image');target.src=img.src;target.alt=img.alt;document.getElementById('gallery-caption').textContent=button.closest('figure').querySelector('figcaption').firstChild.textContent;document.getElementById('gallery-counter').textContent=numberFormat.format(galleryIndex+1)+' / '+numberFormat.format(projectButtons.length);}
projectButtons.forEach((button,index)=>button.addEventListener('click',()=>{galleryOpener=button;renderGallery(index);gallery.showModal();document.body.style.overflow='hidden';}));
document.getElementById('close-gallery').addEventListener('click',()=>gallery.close());document.getElementById('gallery-prev').addEventListener('click',()=>renderGallery(galleryIndex-1));document.getElementById('gallery-next').addEventListener('click',()=>renderGallery(galleryIndex+1));
gallery.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();renderGallery(galleryIndex+1);}else if(e.key==='ArrowRight'){e.preventDefault();renderGallery(galleryIndex-1);}});
gallery.addEventListener('close',()=>{document.body.style.overflow=document.getElementById('mobile-menu')?.open?'hidden':'';if(galleryOpener)galleryOpener.focus({preventScroll:true});});gallery.addEventListener('click',e=>{if(e.target!==gallery)return;const r=gallery.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)gallery.close();});

// Conceptual exploded layer illustration; not an execution specification.
const layerContent={substrate:['از بستر شروع می‌شود.','وضعیت زیرکار، رطوبت و جزئیات اتصال پیش از اجرای پوشش بررسی می‌شوند. روش آماده‌سازی به بستر و سیستم انتخاب‌شده بستگی دارد.'],fibers:['دو جزء، یک ساختار کامپوزیتی.','الیاف شیشه نقش تقویت‌کننده و رزین نقش زمینه را دارد. نوع و آرایش مواد باید با شرایط کاری و طراحی سیستم هماهنگ باشند.'],finish:['سطح نهایی، متناسب با کاربرد.','انتخاب پوشش نهایی و شرایط عمل‌آوری به سیستم منتخب وابسته است. این تصویر، نمایش مفهومی است و جایگزین مشخصات فنی اجرای پروژه نیست.']};
