(()=>{
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const hero=document.querySelector('.about-hero');
const animate=(el,frames,options)=>{if(!reduce.matches&&el.animate)el.animate(frames,options);};
if(hero){[...hero.querySelector('.about-hero-grid').children].forEach((el,i)=>animate(el,[{opacity:.25,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:850,delay:i*140,easing:'cubic-bezier(.2,.7,.2,1)',fill:'backwards'}));}
const buttons=[...document.querySelectorAll('[data-profile]')];const menu=document.querySelector('.about-profile-menu');const content=document.querySelector('.about-profile-content');
if(menu&&content){menu.setAttribute('role','tablist');menu.setAttribute('aria-orientation','vertical');content.classList.add('enhanced');buttons.forEach((b,i)=>{b.id='profile-tab-'+i;b.setAttribute('role','tab');b.setAttribute('aria-controls',b.dataset.profile);const panel=document.getElementById(b.dataset.profile);panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',b.id);});
function select(index,focus){buttons.forEach((b,i)=>{const on=i===index;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;const panel=document.getElementById(b.dataset.profile);panel.hidden=!on;if(on)animate(panel,[{opacity:.2,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:320,easing:'ease-out'});});if(focus)buttons[index].focus();}
buttons.forEach((b,i)=>{b.addEventListener('click',()=>select(i,false));b.addEventListener('keydown',e=>{let next;if(e.key==='ArrowDown'||e.key==='ArrowLeft')next=(i+1)%buttons.length;if(e.key==='ArrowUp'||e.key==='ArrowRight')next=(i-1+buttons.length)%buttons.length;if(e.key==='Home')next=0;if(e.key==='End')next=buttons.length-1;if(next!==undefined){e.preventDefault();select(next,true);}});});select(0,false);}
if('IntersectionObserver' in window){const reveal=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){animate(e.target,[{opacity:.4,transform:'translateY(16px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,easing:'ease-out'});reveal.unobserve(e.target);}});},{threshold:.12});document.querySelectorAll('.about-profile-head,.about-field,.about-workflow li,.about-principle,.about-material').forEach(el=>reveal.observe(el));if(hero){new IntersectionObserver(entries=>{hero.classList.toggle('paused',!entries[0].isIntersecting);}).observe(hero);}}
const links=[...document.querySelectorAll('.about-chapter-nav a')];let pending=false;function mark(){pending=false;let active=null;links.forEach(link=>{const section=document.querySelector(link.getAttribute('href'));if(section&&section.getBoundingClientRect().top<innerHeight*.42)active=link;});links.forEach(link=>{if(link===active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});}addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(mark);}},{passive:true});mark();
const photo=document.querySelector('.about-hero-image');if(photo&&matchMedia('(hover:hover) and (pointer:fine)').matches){photo.addEventListener('pointermove',e=>{if(reduce.matches)return;const r=photo.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;photo.style.transform='perspective(1200px) rotateX('+(-y*2)+'deg) rotateY('+(x*2)+'deg)';});photo.addEventListener('pointerleave',()=>photo.style.transform='');}
})();
